// Arduino Sketch
#include <DShot.h>

DShot esc(9); // Сигнальный провод на пине D9
int motorSpeed = 0;
const int buttonPin = 8;

void setup() {
  pinMode(buttonPin, INPUT_PULLUP);
  esc.begin(DSHOT300); // 300 — это скорость DShot
}

void loop() {
  if (digitalRead(buttonPin) == LOW) {
    motorSpeed = 500; // Примерно 50% мощности
  } else {
    motorSpeed = 0; // Остановка (0 — это не минимум, а полная остановка)
  }

  esc.sendThrottle(motorSpeed);
  delay(10); // DShot требует частого обновления сигнала
}
